#include "migration_status_model.hpp"
#include "migration_status_page.hpp"
#include <QtWidgets>
#include <iostream>
static void check(bool b,const char* why){if(!b)throw std::runtime_error(why);}
template<class F>static void refuses(F f){bool failed=false;try{f();}catch(...){failed=true;}check(failed,"expected refusal");}
static QPushButton* button(QWidget*w,QString text){for(auto b:w->findChildren<QPushButton*>())if(b->text()==text)return b;throw std::runtime_error("button missing");}
int main(int argc,char**argv){QApplication app(argc,argv);try{QJsonArray entries;for(int i=0;i<55;++i)entries.append(QJsonObject{{"id",QString("item%1").arg(i)},{"title",QString("审查项%1").arg(i)},{"route","docs"},{"platform",i%2?"Android":"Windows"},{"module","研究"},{"nativeStatus",i==0?"待迁移":"部分实现"},{"scope",QString("长缺口 ").repeated(500)+QString("尾段%1").arg(i)},{"evidence",QString("opaque:%1").arg(i)},{"verificationDimensions",QJsonObject{{"code","存在"},{"fixture","通过"}}}});QJsonObject snapshot{{"schema","native-migration-status/v1"},{"version","fixture"},{"asOf","2000-01-01"},{"entries",entries},{"scopeNote","审查项不是独立首页"}};auto before=migrationStatus::bytes(snapshot);check(migrationStatus::filter(snapshot,{{"search","尾段54"}}).size()==1,"full gap search");check(migrationStatus::filter(snapshot,{{"platform","Android"}}).size()==27,"platform filter");check(migrationStatus::filter(snapshot,{{"acceptance","未知"}}).size()==55,"missing acceptance unknown not completed");check(migrationStatus::detail(entries[54].toObject()).contains("尾段54"),"full gap preserved");auto duplicate=snapshot;auto ds=entries;ds.append(entries[0]);duplicate["entries"]=ds;refuses([&]{migrationStatus::validate(duplicate);});int jumps=0,reads=0;QString longProof=QString("完整证据原文").repeated(250000);auto w=migrationStatusPage(nullptr,[&]{return snapshot;},[](QString id,QString){return id!="item0";},[&](QString,QString){++jumps;},[&](QString id,QString ref){++reads;check(id=="item1"&&ref=="opaque:1","opaque exact reference");return QJsonObject{{"text",longProof},{"source","fixture"},{"available",true}};});auto rows=w->findChild<QListWidget*>("migrationStatusRows");check(rows->count()==20,"20 rows first page");button(w,"下一页")->click();check(migrationStatusSaveState(w).value("page").toInt()==1&&rows->item(0)->text().contains("item20"),"pagination no dropping");auto saved=migrationStatusSaveState(w);auto copy=migrationStatusPage(nullptr,[&]{return snapshot;});migrationStatusRestoreState(copy,saved);check(migrationStatusSaveState(copy).value("page").toInt()==1,"page recreation");delete copy;button(w,"上一页")->click();rows->setCurrentRow(0);button(w,"查看完整缺口和证据")->click();check(!button(w,"原生入口未接入（禁用，不代表完成）")->isEnabled(),"missing entry visibly disabled");check(migrationStatusBack(w)&&!migrationStatusBack(w),"internal back");rows->setCurrentRow(1);button(w,"查看完整缺口和证据")->click();button(w,"读取所选证据")->click();check(reads==1&&w->findChild<QPlainTextEdit*>("migrationStatusEvidence")->toPlainText().contains(longProof),"complete long proof");saved=migrationStatusSaveState(w);copy=migrationStatusPage(nullptr,[&]{return snapshot;},[](QString,QString){return false;});migrationStatusRestoreState(copy,saved);check(copy->findChild<QPlainTextEdit*>("migrationStatusEvidence")->toPlainText().contains(longProof)&&migrationStatusBack(copy)&&migrationStatusBack(copy)&&!migrationStatusBack(copy),"evidence recreation and internal back");delete copy;check(migrationStatusBack(w),"proof back");auto changed=entries[1].toObject();changed["route"]="wrong";entries[1]=changed;snapshot["entries"]=entries;button(w,"打开已接入原生功能")->click();check(jumps==0,"changed entry refuses whitelist jump");delete w;
if(argc>1){QFile f(QString::fromLocal8Bit(argv[1]));check(f.open(QIODevice::ReadOnly),"actual readonly snapshot");auto actual=migrationStatus::validate(QJsonDocument::fromJson(f.readAll()).object());check(actual.value("entries").toArray().size()==117,"117 audits complete");std::cout<<migrationStatus::summary(actual).toStdString()<<'\n';}check(!before.isEmpty(),"full snapshot export bytes");std::cout<<"PASS migration status full search/filter/pagination/readonly gaps/unknown acceptance/whitelist disabled/long evidence/recreation/stale route refusal; independent only\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}

